\documentclass[border=5pt]{standalone}
\usepackage{tikz}
\usepackage{bytefield}
\usepackage{fontspec}
\setmainfont{FiraMono-Regular}
\tikzset{
    bytefield/box/.style={draw, line width=1pt},
}
\begin{document}
\begin{bytefield}[bitformatting=\small,bitheight=2\baselineskip,bitwidth=0.04\textwidth]{32}
\bitheader{0-31} \\
\bitbox{16}{Source port}  \bitbox{16}{Destination port} \\
\bitbox{32}{Sequence number} \\
\bitbox{32}{Acknowledgment number} \\
\bytefieldsetup{bitheight=4\baselineskip}\bitbox{4}{TCP\\header\\length} 
\bitbox{4}{Reserved} 
\bitbox{1}{\small C\\W\\R} 
\bitbox{1}{\small E\\C\\E} 
\bitbox{1}{\small U\\R\\G} 
\bitbox{1}{\small A\\C\\K} 
\bitbox{1}{\small P\\S\\H} 
\bitbox{1}{\small R\\S\\T} 
\bitbox{1}{\small S\\Y\\N} 
\bitbox{1}{\small F\\I\\N} 
\bitbox{16}{Receive window size} \\
\bitbox{16}{Checksum}  \bitbox{16}{Urgent data pointer} \\
\bitbox{32}{Options (0 or more words)}
\end{bytefield}
\end{document}
